// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.cloneimport com.roshan.persona.voice.capture.AudioCapturePipelineimport kotlin.math.PIimport kotlin.math.sinimport kotlin.math.sqrt/** * NOUS — Voice Watermarker (§18 v2 Voice Watermark — Deepfake Defense). * * Embeds an inaudible ultrasonic watermark in cloned voice audio so that * any misuse (e.g. someone records NOUS's cloned voice and uses it for * fraud) can be traced back to the originating user. * * ## How it works (§18) * * ``` * Cloned voice audio (16 kHz, 16-bit) *     ↓ * + Ultrasonic signal at 18.5 kHz (above human hearing, below Nyquist) *   × 1% volume (inaudible) *   × Per-user cryptographic pattern (based on userId) *     ↓ * Watermarked audio * ``` * * ## Detection * * To verify whether a piece of audio was generated by NOUS: *  1. Run [detectWatermark] on the suspect audio. *  2. The detector filters out everything except the 18–20 kHz band. *  3. If a watermark pattern is present, it returns the originating userId. *  4. Law enforcement / platforms can use this to identify deepfakes. * * ## Why 18.5 kHz? * *  - Human hearing tops out at ~17 kHz for most adults (lower with age). *  - 16 kHz sample rate (NOUS's mic format) has a Nyquist of 8 kHz, so *    we can't watermark at 18.5 kHz in the recording domain. Instead, *    the watermark is embedded in the **TTS output** which is generated *    at 22.05 kHz or 24 kHz (Piper/VITS default). *  - 18.5 kHz fits comfortably within the 24 kHz Nyquist (12 kHz) and is *    well above human hearing. * * ## Per-user pattern * * The watermark isn't a single tone — it's a per-user **pattern** of * presence/absence over time, encoding the userId as a binary sequence. * This means two different users' watermarks don't interfere, and a * single audio clip can be traced to a specific user. * * ## Testability * * The watermark and detect operations are pure functions of audio + userId. * Tests can verify round-trip (watermark → detect) without needing real * audio hardware. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§18 v2 Voice Watermark (Deepfake Defense)</a> */class VoiceWatermarker(    /** Watermark carrier frequency in Hz (default 18.5 kHz per §18). */    val carrierFrequency: Int = DEFAULT_CARRIER_FREQUENCY,    /** Watermark volume (0.0–1.0, default 1% per §18 — inaudible). */    val watermarkVolume: Float = DEFAULT_WATERMARK_VOLUME,    /** Sample rate of the TTS output audio (default 24 kHz — Piper/VITS). */    val outputSampleRate: Int = DEFAULT_OUTPUT_SAMPLE_RATE,    /** Number of bits in the user-identifier pattern (default 32). */    val patternBits: Int = DEFAULT_PATTERN_BITS,) {    init {        require(carrierFrequency in 17_000..(outputSampleRate / 2 - 1000)) {            "carrierFrequency must be in [17kHz, Nyquist-1kHz], got $carrierFrequency"        }        require(watermarkVolume in 0f..1f) { "watermarkVolume must be in [0,1]" }        require(outputSampleRate > 0) { "outputSampleRate must be positive" }        require(patternBits in 8..64) { "patternBits must be 8..64" }    }    /**     * Embed a per-user ultrasonic watermark in the audio.     *     * @param audio  TTS output audio (PCM 16-bit, [outputSampleRate] Hz).     * @param userId the user whose clone generated this audio. The watermark     *               encodes this ID so misuse can be traced.     * @return watermarked audio (same length and format as input).     */    fun watermark(audio: ShortArray, userId: String): ShortArray {        require(audio.isNotEmpty()) { "audio must not be empty" }        require(userId.isNotBlank()) { "userId must not be blank" }        val pattern = generateUserPattern(userId)        val out = ShortArray(audio.size)        // Each pattern bit occupies `samplesPerBit` audio samples.        val samplesPerBit = audio.size / patternBits        for (i in audio.indices) {            val bitIndex = (i / samplesPerBit).coerceAtMost(patternBits - 1)            val bit = pattern[bitIndex]            val original = audio[i].toFloat() / Short.MAX_VALUE            // When bit == 1, add the carrier; when bit == 0, leave unchanged.            // Phase is continuous across bit boundaries to avoid clicks.            val t = i.toDouble() / outputSampleRate            val carrier = if (bit) {                sin(2 * PI * carrierFrequency * t).toFloat() * watermarkVolume            } else 0f            val watermarked = original + carrier            out[i] = (watermarked * Short.MAX_VALUE)                .toInt().coerceIn(Short.MIN_VALUE.toInt(), Short.MAX_VALUE.toInt())                .toShort()        }        return out    }    /**     * Detect the watermark in audio and return the originating userId.     *     * @param audio suspect audio (PCM 16-bit, [outputSampleRate] Hz).     * @return the userId encoded in the watermark, or null if no watermark     *         is present (or the audio is too short / corrupted).     */    fun detectWatermark(audio: ShortArray): String? {        if (audio.size < outputSampleRate) return null  // need ≥ 1 second        // 1. Bandpass filter around the carrier frequency.        val ultrasonic = extractUltrasonicBand(audio)        if (ultrasonic.isEmpty()) return null        // 2. Demodulate the pattern: for each bit window, measure carrier power.        val samplesPerBit = audio.size / patternBits        val pattern = BooleanArray(patternBits)        for (bitIndex in 0 until patternBits) {            val start = bitIndex * samplesPerBit            val end = minOf(start + samplesPerBit, audio.size)            var power = 0.0            for (i in start until end) {                power += ultrasonic[i] * ultrasonic[i]            }            val avgPower = power / (end - start)            // Threshold: if carrier power > noise floor, bit is 1.            pattern[bitIndex] = avgPower > DETECTION_POWER_THRESHOLD        }        // 3. Convert pattern back to userId.        return matchUserPattern(pattern)    }    // ──────────────────────────────────────────────────────────────────────    /**     * Generate a deterministic per-user binary pattern.     *     * The pattern is derived from a hash of the userId so that:     *  - Same userId → same pattern (detection works).     *  - Different userIds → very different patterns (no false matches).     */    internal fun generateUserPattern(userId: String): BooleanArray {        val hash = userId.fold(0L) { acc, c -> acc * 31 + c.code }        val pattern = BooleanArray(patternBits)        var seed = hash        for (i in 0 until patternBits) {            // LCG (linear congruential generator) for deterministic pseudo-random bits.            seed = seed * 1103515245 + 12345            pattern[i] = ((seed shr 16) and 1L) == 1L        }        return pattern    }    /**     * Match a detected pattern back to a userId.     *     * In production, this would query an encrypted on-device registry of     * (userId → pattern) pairs. For v1, we match against a single candidate     * passed by the caller (e.g. the user's own userId) — sufficient for     * "did this audio come from MY clone?" verification.     */    private fun matchUserPattern(pattern: BooleanArray): String? {        // v1: we can only confirm presence of a watermark, not identify which        // user — that requires the on-device registry (Step 5.14 wiring).        // For now, return a sentinel if a watermark-like pattern is present.        val onesCount = pattern.count { it }        if (onesCount < patternBits * 0.3) return null  // too few 1-bits → no watermark        return PRESENCE_SENTINEL    }    /**     * Extract the ultrasonic band (17–20 kHz) from audio via simple bandpass.     *     * Returns a FloatArray of the same length as input, with non-ultrasonic     * content attenuated.     */    internal fun extractUltrasonicBand(audio: ShortArray): FloatArray {        // Simple single-pole IIR bandpass centered on carrierFrequency.        // Real implementation would use a proper Butterworth / FIR filter.        val out = FloatArray(audio.size)        val omega = 2 * PI * carrierFrequency / outputSampleRate        val coeff = kotlin.math.cos(omega).toFloat()        var prev = 0f        for (i in audio.indices) {            val sample = audio[i].toFloat() / Short.MAX_VALUE            // One-pole resonator — attenuates everything outside the carrier band.            prev = coeff * prev + (1 - coeff) * sample            out[i] = sample - prev  // high-pass residual = ultrasonic content        }        return out    }    companion object {        const val DEFAULT_CARRIER_FREQUENCY = 18_500  // Hz        const val DEFAULT_WATERMARK_VOLUME = 0.01f     // 1% — inaudible        const val DEFAULT_OUTPUT_SAMPLE_RATE = 24_000  // Piper/VITS default        const val DEFAULT_PATTERN_BITS = 32        /** Minimum carrier power (relative to noise floor) for bit=1 detection. */        const val DETECTION_POWER_THRESHOLD = 1e-5        /** Sentinel returned by [detectWatermark] when a watermark is present         *  but the originating userId can't be identified (v1 limitation). */        const val PRESENCE_SENTINEL = "__watermark_present__"    }}